def sample(d):
 tokens=re.findall(r'[MLQ]|-?\d+(?:\.\d+)?',d);out=[];i=0;cmd='M'
 while i<len(tokens):
  if tokens[i] in ['M','L','Q']:cmd=tokens[i];i+=1
  if cmd in ['M','L']:
   out.append([float(tokens[i]),float(tokens[i+1])]);i+=2
  else:
   x0,y0=out[-1];cx,cy,x,y=map(float,tokens[i:i+4]);i+=4
   out.extend([[(1-t)**2*x0+2*(1-t)*t*cx+t*t*x,(1-t)**2*y0+2*(1-t)*t*cy+t*t*y] for t in [j/16 for j in range(1,17)]])
 return out

def prior(index):
 p=PRIOR[index]
 arms=[sample(d) for d in p['arms']];legs=[sample(d) for d in p['legs']];torso=sample(p['torso'])
 shoulder=[sum(a[0][i] for a in arms)/len(arms) for i in [0,1]];hip=[sum(a[0][i] for a in legs)/len(legs) for i in [0,1]]
 if math.dist(torso[-1],hip)>25 or math.dist(torso[0],torso[-1])<15:torso=[shoulder,hip]
 arms=[[shoulder,*a] if math.dist(shoulder,a[0])>1 else a for a in arms]
 return {'head':p['head'][:2],'torso':torso,'arms':arms,'legs':legs,'props':[],'front':False}
